package com.skyrpg.brainrots.client.model;

import net.minecraft.client.model.geom.builders.LayerDefinition;

/**
 * Every brainrot model that has been drawn. GENERATED by tools/art/generate_brainrots.py from the layouts present:
 * don't edit it by hand.
 */
public final class BrainrotLayouts {
    /** A kind's cubes, its part paths ("body/head"), and whether it has a glow texture. */
    public record Entry(LayerDefinition layer, String[] parts, boolean glow) {
    }

    private BrainrotLayouts() {
    }

    /** The kind's model, or null when it hasn't been drawn yet. */
    public static Entry get(String kind) {
        return switch (kind) {
            case "tung_tung_sahur" -> new Entry(TungTungSahurLayout.create(), TungTungSahurLayout.PARTS, TungTungSahurLayout.GLOW);
            case "tralalero_tralala" -> new Entry(TralaleroTralalaLayout.create(), TralaleroTralalaLayout.PARTS, TralaleroTralalaLayout.GLOW);
            case "bombardiro_crocodilo" -> new Entry(BombardiroCrocodiloLayout.create(), BombardiroCrocodiloLayout.PARTS, BombardiroCrocodiloLayout.GLOW);
            case "ballerina_cappuccina" -> new Entry(BallerinaCappuccinaLayout.create(), BallerinaCappuccinaLayout.PARTS, BallerinaCappuccinaLayout.GLOW);
            case "brr_brr_patapim" -> new Entry(BrrBrrPatapimLayout.create(), BrrBrrPatapimLayout.PARTS, BrrBrrPatapimLayout.GLOW);
            case "lirili_larila" -> new Entry(LiriliLarilaLayout.create(), LiriliLarilaLayout.PARTS, LiriliLarilaLayout.GLOW);
            case "chimpanzini_bananini" -> new Entry(ChimpanziniBananiniLayout.create(), ChimpanziniBananiniLayout.PARTS, ChimpanziniBananiniLayout.GLOW);
            case "bombombini_gusini" -> new Entry(BombombiniGusiniLayout.create(), BombombiniGusiniLayout.PARTS, BombombiniGusiniLayout.GLOW);
            case "trippi_troppi" -> new Entry(TrippiTroppiLayout.create(), TrippiTroppiLayout.PARTS, TrippiTroppiLayout.GLOW);
            case "cappuccino_assassino" -> new Entry(CappuccinoAssassinoLayout.create(), CappuccinoAssassinoLayout.PARTS, CappuccinoAssassinoLayout.GLOW);
            case "frigo_camelo" -> new Entry(FrigoCameloLayout.create(), FrigoCameloLayout.PARTS, FrigoCameloLayout.GLOW);
            case "la_vaca_saturno" -> new Entry(LaVacaSaturnoLayout.create(), LaVacaSaturnoLayout.PARTS, LaVacaSaturnoLayout.GLOW);
            case "boneca_ambalabu" -> new Entry(BonecaAmbalabuLayout.create(), BonecaAmbalabuLayout.PARTS, BonecaAmbalabuLayout.GLOW);
            case "glorbo_fruttodrillo" -> new Entry(GlorboFruttodrilloLayout.create(), GlorboFruttodrilloLayout.PARTS, GlorboFruttodrilloLayout.GLOW);
            case "burbaloni_luliloli" -> new Entry(BurbaloniLuliloliLayout.create(), BurbaloniLuliloliLayout.PARTS, BurbaloniLuliloliLayout.GLOW);
            default -> null;
        };
    }
}
